<?php
namespace Tests\Feature;
use App\Enums\ApprovalStatus;use App\Enums\ApprovalType;use App\Enums\DigitalTransactionStatus;use App\Enums\UserRole;use App\Models\DigitalTransaction;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class NextStaffDigitalApiTest extends TestCase{use RefreshDatabase;
public function test_cashier_can_request_idempotent_manual_transaction():void{$cashier=User::factory()->create(['role'=>UserRole::Cashier]);Sanctum::actingAs($cashier,['staff:digital']);$key=(string)Str::uuid();$payload=['type'=>'pulsa','provider'=>'Provider Uji','destination'=>'081234567890','destination_confirmation'=>'081234567890','nominal'=>10000,'cost_price'=>9500,'selling_price'=>11000,'admin_fee'=>0,'status'=>'berhasil','idempotency_key'=>$key];$first=$this->postJson('/api/v1/staff/digital-transactions',$payload)->assertStatus(202);$this->assertDatabaseCount('digital_transactions',1);$transaction=DigitalTransaction::firstOrFail();$this->assertSame(DigitalTransactionStatus::Pending,$transaction->status);$this->assertDatabaseHas('approval_requests',['type'=>ApprovalType::DigitalTransaction->value,'status'=>ApprovalStatus::Pending->value,'subject_id'=>$transaction->id]);$this->postJson('/api/v1/staff/digital-transactions',$payload)->assertOk()->assertJsonPath('data.transaction_number',$first->json('data.transaction_number'));$this->assertDatabaseCount('digital_transactions',1);}
public function test_listing_masks_manual_destinations_and_exposes_topup_summary():void{$admin=User::factory()->create(['role'=>UserRole::Admin]);DigitalTransaction::create(['transaction_number'=>'DIG-NEXT-001','user_id'=>$admin->id,'type'=>'pulsa','destination'=>'081234567890','nominal'=>10000,'cost_price'=>9000,'selling_price'=>10000,'admin_fee'=>0,'idempotency_key'=>(string)Str::uuid(),'request_fingerprint'=>'hash','status'=>DigitalTransactionStatus::Success]);Sanctum::actingAs($admin,['staff:digital']);$this->getJson('/api/v1/staff/digital-transactions')->assertOk()->assertJsonPath('data.transactions.0.destination','081******890')->assertJsonMissingPath('data.transactions.0.idempotency_key')->assertJsonPath('data.pagination.topup.total',0);}
public function test_digital_access_requires_operational_role_and_ability():void{$customer=User::factory()->create(['role'=>UserRole::Customer]);Sanctum::actingAs($customer,['staff:digital']);$this->getJson('/api/v1/staff/digital-transactions')->assertForbidden();$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:dashboard']);$this->getJson('/api/v1/staff/digital-transactions')->assertForbidden();}
}